<?php
declare(strict_types=1);namespace App\Http\Controllers\Finance;use App\Http\Controllers\Controller;use App\Http\Requests\Finance\PaymentRequest;use App\Models\{Student};use App\Models\Finance\{StudentInvoice,StudentPayment};use App\Services\Finance\PaymentService;use Illuminate\Http\Request;class StudentPaymentController extends Controller{public function index(Request $r){$q=StudentPayment::with(['student','invoice']);if($r->filled('method'))$q->where('payment_method',$r->method);if($r->filled('search'))$q->whereHas('student',fn($x)=>$x->where('full_name','like','%'.$r->search.'%')->orWhere('nis','like','%'.$r->search.'%')->orWhere('nisn','like','%'.$r->search.'%'));return view('finance.payments.index',['payments'=>$q->latest('paid_at')->paginate(20)->withQueryString()]);}public function create(Request $r){$students=Student::where('status','active')->orderBy('full_name')->get();$invoices=StudentInvoice::with('student')->where('outstanding_amount','>',0)->whereIn('status',['open','partial','overdue'])->when($r->student_id,fn($q,$id)=>$q->where('student_id',$id))->get();return view('finance.payments.form',compact('students','invoices'));}public function store(PaymentRequest $r,PaymentService $s){$p=$s->record(StudentInvoice::findOrFail($r->integer('invoice_id')),$r->validated(),$r->user()->id);return redirect()->route('finance.payments.show',$p)->with('success','Pembayaran berhasil dicatat.');}public function show(StudentPayment $payment){return view('finance.payments.show',['payment'=>$payment->load(['student.activeClassroomMembership.classroom','invoice.items.feeType','creator','receiptDeliveries'])]);}public function receipt(StudentPayment $payment){return view('finance.payments.receipt',['payment'=>$payment->load(['student.activeClassroomMembership.classroom','invoice.items.feeType','creator'])]);}}
